return {["fb27_01"]={["down"]=[[fb27_02]],["dsc"]=[[你眼前出现一个山间湖泊，这就是著名的太乙池，传为唐天宝年间地震造成，四周高峰环列，池面碧波荡漾，山光水影，风景十分优美。]],["enterable"]=1,["id"]=[[fb27_01]],["item1"]=[[fb27item20]],["name"]=[[太乙池]],["permission"]=1,["role1"]=[[fb27r01_1]],["role2"]=[[fb27r01_2]],["role3"]=[[fb27r01_3]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb27_02"]={["down"]=[[fb27_04]],["dsc"]=[[这是一条非常崎岖难行的山路，在此处可眺望终南山的景色，只见山险岭峻，山川毓秀，不少鸟ㄦ在枝头高声啼唱不绝。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_02]],["name"]=[[山道]],["permission"]=1,["role1"]=[[fb27r05_1]],["role2"]=[[fb27r05_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_01]],["visible"]=1},["fb27_03"]={["down"]=[[fb27_06]],["dsc"]=[[这里是重阳宫以前的旧址，王重阳曾在此清修，后来手创全真教后，此地的布局实在太小，就将重阳宫迁到东面山上，将此地重新改名为遇真宫，以纪念得道之意。]],["enterable"]=1,["id"]=[[fb27_03]],["item1"]=[[fb27item100]],["item2"]=[[lylitem1]],["name"]=[[遇真宫]],["permission"]=2,["role1"]=[[fb27r03_1]],["role2"]=[[fb27r03_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb27_04"]={["down"]=[[fb27_10]],["dsc"]=[[走在林中，只听得脚下沙沙的落叶声，四周昏昏暗暗的，不时几道日光穿过浓密的枝头，投射而下。偶而远处几声兽吼声，更添了一份神秘感。往北、南各有一条小径。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb27_04]],["name"]=[[树林]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb27_02]],["visible"]=1},["fb27_05"]={["down"]=[[fb27_13]],["dsc"]=[[这里是半山腰的一个小凉亭，游客们爬山爬的累了，就转个弯到这里来坐一坐，歇一歇脚。从这里看下去，刚好可以看见翠屏峰的峰顶。]],["enterable"]=1,["id"]=[[fb27_05]],["name"]=[[半山亭]],["permission"]=2,["role1"]=[[fb27item12]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb27_06"]={["down"]=[[fb27_14]],["dsc"]=[[跨过石阶，眼前是一座石头砌成的小小拱桥。桥上栏杆上雕龙描凤，栩栩如生。这里的山势非常陡峻，往下一看，悬崖壁立，脚下白云飘过，真不知身在何境。]],["enterable"]=1,["id"]=[[fb27_06]],["item1"]=[[fb27r06_101]],["name"]=[[访真桥]],["permission"]=1,["role1"]=[[fb27r06_1]],["role2"]=[[fb27r06_2]],["role3"]=[[fb27r06_3]],["role4"]=[[fb27r06_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_03]],["visible"]=1},["fb27_07"]={["down"]=[[fb27_15]],["dsc"]=[[这条山路盘终南山主峰而上，山路贴着石璧凿出，只容一人可过，形势极为险峻。往东下和南上各是一条山路。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_07]],["item1"]=[[fb27item14]],["item2"]=[[fb27item16]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb27_08]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb27_08"]={["dsc"]=[[这条山路盘终南山主峰而上，山路贴着石璧凿出，只容一人可过，形势极为险峻。往东下和西上各是一条山路。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_08]],["item1"]=[[fb27item14]],["item2"]=[[fb27item15]],["left"]=[[fb27_07]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb27_09]],["role1"]=[[fb27r08_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb27_09"]={["down"]=[[fb27_17]],["dsc"]=[[这条山路盘终南山主峰而上，山路贴着石璧凿出，只容一人可过，形势极为险峻。往南下和西上各是一条山路。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_09]],["item1"]=[[fb27item14]],["item2"]=[[fb27item15]],["left"]=[[fb27_08]],["name"]=[[山路]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb27_10"]={["dsc"]=[[这是一条非常崎岖难行的山路，在此处可眺望终南山的景色，只见山险岭峻，山川毓秀，不少鸟ㄦ在枝头高声啼唱不绝。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_10]],["name"]=[[山道]],["permission"]=1,["rightDown"]=[[fb27_18]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_04]],["visible"]=1},["fb27_11"]={["down"]=[[fb27_18]],["dsc"]=[[这是一座位於终南山北麓的小寺。寺院中的一口古井，名为烟雾井。因为每天清晨都会有一股巨大的烟雾，自井里袅袅升起，不少游客来此，就是为了一观此奇景。]],["enterable"]=1,["id"]=[[fb27_11]],["name"]=[[草堂寺]],["permission"]=2,["role1"]=[[fb27item11]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb27_12"]={["down"]=[[fb27_19]],["dsc"]=[[这是一条整齐的石板路，依山而建，随着山势的曲折蜿蜒曲折。由于山势陡了，当初修建这条石阶时肯定费了不小的功夫。走到这里，已经可以看见重阳观的檐角了。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_12]],["name"]=[[石阶]],["permission"]=1,["right"]=[[fb27_13]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb27_13"]={["down"]=[[fb27_20]],["dsc"]=[[这是一条整齐的石板路，依山而建，随着山势的曲折蜿蜒曲折。由于山势陡了，当初修建这条石阶时肯定费了不小的功夫。走到这里，已经可以看见重阳观的檐角了。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_13]],["left"]=[[fb27_12]],["name"]=[[石阶]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb27_05]],["visible"]=1},["fb27_14"]={["down"]=[[fb27_21]],["dsc"]=[[这是一条整齐的石板路，依山而建，随着山势的曲折蜿蜒曲折。由于山势陡了，当初修建这条石阶时肯定费了不小的功夫。走到这里，已经可以看见重阳观的檐角了。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_14]],["name"]=[[石阶]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb27_06]],["visible"]=1},["fb27_15"]={["dsc"]=[[这条山路盘终南山主峰而上，山路贴着石璧凿出，只容一人可过，形势极为险峻。往北下是一条山路。往东上就是终南山主峰。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_15]],["item1"]=[[fb27item14]],["item2"]=[[fb27item15]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb27_16]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_07]],["visible"]=1},["fb27_16"]={["down"]=[[fb27_26]],["dsc"]=[[此时你已身在终南山主峰，视野更为广阔。往低望去，群山尽皆匍匐在脚下。一块巨石立在一旁，似乎刻了什麽东西。往西和南各是一条山路。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_16]],["item1"]=[[fb27item14]],["item2"]=[[fb27item15]],["left"]=[[fb27_15]],["name"]=[[终南山主峰]],["permission"]=2,["role1"]=[[fb27r16_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb27_17"]={["down"]=[[fb27_23]],["dsc"]=[[这条山路盘终南山主峰而上，山路贴着石璧凿出，只容一人可过，形势极为险峻。往远处望去。往东下和北上各是一条山路。往南下是白马潭。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_17]],["item1"]=[[fb27item14]],["item2"]=[[fb27item15]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb27_18]],["role1"]=[[fb27r17_1]],["role2"]=[[fb27r17_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_09]],["visible"]=1},["fb27_18"]={["dsc"]=[[这是一条非常崎岖难行的山路，在此处可眺望终南山的景色，只见山险岭峻，山川毓秀，不少鸟ㄦ在枝头高声啼唱不绝。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_18]],["left"]=[[fb27_17]],["leftUp"]=[[fb27_10]],["name"]=[[山路]],["permission"]=1,["right"]=[[fb27_19]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_11]],["visible"]=1},["fb27_19"]={["down"]=[[fb27_24]],["dsc"]=[[这是一个位於终南山山腰的圆坪，四周群山环抱。山脚下有一座大池。每年腊月，全真派便於此地举行大校，以考察门下弟子在这一年间的进境。]],["enterable"]=1,["fightBackground"]=[[擂台]],["id"]=[[fb27_19]],["left"]=[[fb27_18]],["name"]=[[大校场]],["permission"]=1,["role1"]=[[fb27r19_1]],["role2"]=[[fb27r19_2]],["role3"]=[[fb27r19_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_12]],["visible"]=1},["fb27_20"]={["down"]=[[fb27_25]],["dsc"]=[[石阶旁立着一块大岩石，上面斑斑驳驳的尽是砍伤。这块大岩石便是全真教的试剑岩，天下的英雄来到这里，望着先辈们练剑时在岩石上的砍痕，无不肃然起敬。]],["enterable"]=1,["id"]=[[fb27_20]],["name"]=[[试剑岩]],["permission"]=1,["right"]=[[fb27_21]],["role1"]=[[fb27r20_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_13]],["visible"]=1},["fb27_21"]={["dsc"]=[[这里是全真教的教碑所在地，路旁立着一块大碑。再往东走就是天下闻名的道家玄门正宗--全真教的大门了。北面有一条石阶，不知道通向哪里，往西是下山的路。]],["enterable"]=1,["id"]=[[fb27_21]],["left"]=[[fb27_20]],["name"]=[[教碑]],["permission"]=1,["right"]=[[fb27_22]],["role1"]=[[fb27item18]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_14]],["visible"]=1},["fb27_22"]={["dsc"]=[[你已走到了终南山半山腰，前面就是全真教的总部重阳宫了。殿宇依山而筑，高低错落有致。]],["enterable"]=1,["id"]=[[fb27_22]],["left"]=[[fb27_21]],["name"]=[[重阳宫山道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb27_23"]={["dsc"]=[[潭边有块奇石，这石头中间低两头高，石头的前半截伸在水里，後半截留在岸上，老远看去活似一匹腾空欲飞的烈马，因此称此潭为白马潭。]],["enterable"]=1,["id"]=[[fb27_23]],["item1"]=[[bfr23_1]],["item2"]=[[ycitem1]],["item3"]=[[ycitem2]],["name"]=[[白马潭]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb27_17]],["visible"]=1},["fb27_24"]={["down"]=[[fb27_27]],["dsc"]=[[这是一条非常崎岖难行的山路，在此处可眺望终南山的景色，只见山险岭峻，山川毓秀，不少鸟ㄦ在枝头高声啼唱不绝。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_24]],["item1"]=[[fb27item105]],["name"]=[[山道]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb27_19]],["visible"]=1},["fb27_25"]={["down"]=[[fb27_28]],["dsc"]=[[这是一条整齐的石板路，依山而建，随着山势的曲折蜿蜒曲折。由于山势陡了，当初修建这条石阶时肯定费了不小的功夫。走到这里，已经可以看见重阳观的檐角了。]],["enterable"]=1,["fightBackground"]=[[石阶]],["id"]=[[fb27_25]],["name"]=[[石阶]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb27_20]],["visible"]=1},["fb27_26"]={["down"]=[[fb27_29]],["dsc"]=[[这条山路盘终南山主峰而上，山路贴着石璧凿出，只容一人可过，形势极为险峻。南下是一块空地。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_26]],["item1"]=[[fb27item14]],["item2"]=[[fb27item15]],["name"]=[[山路]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb27_16]],["visible"]=1},["fb27_27"]={["down"]=[[fb27_30]],["dsc"]=[[一路过来，山路是越来越险。只见一块大岩石挡在路中，自空凭临，宛似一个老妇弯腰俯视，但形状阴森可怖，令人望而生畏。不少游客在此驻足观看。]],["enterable"]=1,["id"]=[[fb27_27]],["name"]=[[老妪岩]],["permission"]=1,["role1"]=[[fb27r27_1]],["role2"]=[[fb27r27_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_24]],["visible"]=1},["fb27_28"]={["dsc"]=[[这里是终南山上的观日台，不知哪朝哪代何人在这里修筑了这个平台，用来观瞻日出的美景。这里的山势非常陡峻，往下一看，悬崖壁立，脚下白云飘过，真不知身在何境。]],["enterable"]=1,["id"]=[[fb27_28]],["item1"]=[[ycitem3]],["name"]=[[观日台]],["permission"]=1,["role1"]=[[fb27r28_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_25]],["visible"]=1},["fb27_29"]={["down"]=[[fb27_32]],["dsc"]=[[这是终南山山腰处的一块空地，地势平坦。北面一条小路直攀山璧而上，通往是终南山主峰。南边和西边一大片密林，只闻阵阵琴声自林中传出。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb27_29]],["name"]=[[空地]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb27_26]],["visible"]=1},["fb27_30"]={["down"]=[[fb27_34]],["dsc"]=[[这位於终南山间的一大片树林，生的颇为茂密。走在其间，只听得脚下沙沙的落叶声，四周昏昏暗暗的，不时几道日光穿过浓密的枝头，投射而下。偶而远处几声兽吼声，更添了一份神秘感。往北、南各有一条小径。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb27_30]],["name"]=[[树林]],["permission"]=1,["right"]=[[fb27_31]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_27]],["visible"]=1},["fb27_31"]={["dsc"]=[[此处位於终南山脉东部的太阳山上。只见山峰直上直下，像刀切般的陡峭，只山腰上有一个碾盘子粗的石洞，不时冒出一股黑气，怪可怕的。往西是一片树林。]],["enterable"]=1,["id"]=[[fb27_31]],["left"]=[[fb27_30]],["name"]=[[黑凤洞]],["permission"]=2,["role1"]=[[fb27item13]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb27_32"]={["dsc"]=[[再往前一段便是古陵了。]],["enterable"]=1,["id"]=[[fb27_32]],["name"]=[[古陵]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb27_29]],["visible"]=1},["fb27_33"]={["dsc"]=[[只见此处颇为荒凉，是一处寺院的遗址。四周青松翠柏环绕，寺院的断垣残璧依稀可见，似乎还是一座不小的寺院。往北是一片平原。]],["enterable"]=1,["id"]=[[fb27_33]],["item1"]=[[fb27item3]],["item2"]=[[fb27item19]],["name"]=[[佛爷掌]],["permission"]=2,["right"]=[[fb27_34]],["role1"]=[[fb27r33_100]],["role2"]=[[fb27r33_101]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb27_34"]={["dsc"]=[[此处位於终南山中部的翠华山附近。传说商朝末年，姜子牙率兵伐纣攻打长安时，粮草短缺，在此获神禾老汉之助，得米万斛，因此命名为神禾原。]],["enterable"]=1,["id"]=[[fb27_34]],["left"]=[[fb27_33]],["name"]=[[神禾原]],["permission"]=1,["rightDown"]=[[fb27_35]],["role1"]=[[fb27r34_1]],["role2"]=[[fb27r34_2]],["role3"]=[[fb27r34_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_30]],["visible"]=1},["fb27_35"]={["dsc"]=[[这位於终南山间的一大片树林，生的颇为茂密。走在其间，只听得脚下沙沙的落叶声，四周昏昏暗暗的，不时几道日光穿过浓密的枝头，投射而下。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb27_35]],["leftUp"]=[[fb27_34]],["name"]=[[树林]],["permission"]=1,["right"]=[[fb27_36]],["role1"]=[[fb27item109]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb27_36"]={["down"]=[[fb27_37]],["dsc"]=[[一路过来，山路是越来越险。前方不远处的一块巨石，便是有名的抱子岩。再看几眼，觉那岩生得甚是奇怪，就如一个妇人抱着个孩子般，细心呵护……]],["enterable"]=1,["id"]=[[fb27_36]],["left"]=[[fb27_35]],["name"]=[[抱子岩]],["permission"]=1,["role1"]=[[fb27r36_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb27_37"]={["down"]=[[fb27_39]],["dsc"]=[[这位於终南山间的一大片树林，生的颇为茂密。走在其间，只听得脚下沙沙的落叶声，四周昏昏暗暗的，不时几道日光穿过浓密的枝头，投射而下。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb27_37]],["item1"]=[[ycitem4]],["name"]=[[树林]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb27_36]],["visible"]=1},["fb27_38"]={["down"]=[[fb27_40]],["dsc"]=[[这里是翠屏峰的峰顶。悬崖边建有一个小亭子，你走进亭中凭拦远望，远处的山间白云漂浮缭绕，好像修筑着什么建筑，山景清丽，可惜被白云尽遮住了。]],["id"]=[[fb27_38]],["item1"]=[[fb27item9]],["item2"]=[[fb27item10]],["item3"]=[[fb27item101]],["name"]=[[翠屏峰顶]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb27_39"]={["down"]=[[fb27_41]],["dsc"]=[[这是一条非常崎岖难行的山路，一路蜿蜒盘山而上，沿途均是葱郁的古柏山林，蔚然森秀。在此处可眺望终南山的景色，只见山险岭峻，山川毓秀。]],["fightBackground"]=[[山外]],["id"]=[[fb27_39]],["item1"]=[[fb27item10]],["name"]=[[山路]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb27_37]]},["fb27_40"]={["down"]=[[fb27_44]],["dsc"]=[[绕过翠屏谷的山壁，眼前是一片大柏树林，想是由于山壁挡住了视线，在山下的山路上根本想不到这里的柏树竟会有这么密这么高。]],["fightBackground"]=[[柏林]],["id"]=[[fb27_40]],["item1"]=[[fb27item10]],["item2"]=[[fb27item10]],["name"]=[[柏林]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb27_38]]},["fb27_41"]={["dsc"]=[[一路过来，怪石林立，令人称奇。前方不远处的两块巨石，左边的一块像月亮，右边的那块像太阳，夹道而立，便如一对门神，只留当中一条宽约一人多的小道，让人通过。]],["id"]=[[fb27_41]],["name"]=[[日月岩]],["permission"]=1,["right"]=[[fb27_42]],["role1"]=[[fb27r41_1]],["role2"]=[[fb27r41_2]],["role3"]=[[fb27r41_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_39]]},["fb27_42"]={["dsc"]=[[这是一条非常崎岖难行的山路，一路蜿蜒盘山而上，沿途均是葱郁的古柏山林，蔚然森秀。在此处可眺望终南山的景色，只见山险岭峻，山川毓秀。]],["fightBackground"]=[[山外]],["id"]=[[fb27_42]],["left"]=[[fb27_41]],["name"]=[[山路]],["permission"]=1,["right"]=[[fb27_43]],["stepMusic"]=[[jiaobu]]},["fb27_43"]={["down"]=[[fb27_45]],["dsc"]=[[这金莲阁位於终南山山腰间，形势颇为险要。金莲阁後有一口碗口粗的涌泉，泉水碧绿透明，香甜诱人，在当地颇为有名，不少人特别来此，只为了取这ㄦ的水来泡茶。]],["id"]=[[fb27_43]],["item1"]=[[fb27item8]],["left"]=[[fb27_42]],["name"]=[[金莲阁]],["permission"]=1,["role1"]=[[fb27r43_1]],["role2"]=[[fb27r43_2]],["stepMusic"]=[[jiaobu]]},["fb27_44"]={["down"]=[[fb27_46]],["dsc"]=[[你的面前是一座形如屏风的大山壁，山壁上郁郁葱葱都是树，一眼看过去，全是一片翠绿色。这就是此地名叫翠屏谷的由来。从这里继续北上，就到了终南山上的柏树林了。]],["id"]=[[fb27_44]],["name"]=[[翠屏谷]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb27_40]]},["fb27_45"]={["down"]=[[fb27_49]],["dsc"]=[[这是一条非常崎岖难行的山路，一路蜿蜒盘山而上，沿途均是葱郁的古柏山林，蔚然森秀。在此处可眺望终南山的景色，只见山险岭峻，山川毓秀。]],["fightBackground"]=[[山外]],["id"]=[[fb27_45]],["name"]=[[山路]],["permission"]=1,["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_43]]},["fb27_46"]={["dsc"]=[[前面好像有一个大山谷，走到这里，树木多了些，全都是柏树。西面是一条弯曲的山路，隐藏在山间，要在夜里还真看不出来。]],["fightBackground"]=[[山外]],["id"]=[[fb27_46]],["leftDown"]=[[fb27_51]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb27_66]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_44]]},["fb27_47"]={["down"]=[[fb27_52]],["dsc"]=[[这是一条位於终南山脚，鲜为人知的小径。四周古木叁天，树林苍翠，遍地山花，枝头啼鸟唱和不绝。往南可看到一条小河。往东可通往山林深处。]],["fightBackground"]=[[山外]],["id"]=[[fb27_47]],["item1"]=[[fb27item106]],["name"]=[[山间小径]],["permission"]=2,["right"]=[[fb27_48]],["stepMusic"]=[[jiaobu]]},["fb27_48"]={["dsc"]=[[这是一条位於终南山脚，鲜为人知的小径。四周古木叁天，树林苍翠，遍地山花，枝头啼鸟唱和不绝。往西和东南可通往山林深处。]],["fightBackground"]=[[山外]],["id"]=[[fb27_48]],["item1"]=[[2019qxhdd1]],["left"]=[[fb27_47]],["name"]=[[山间小径]],["permission"]=2,["rightDown"]=[[fb27_53]],["stepMusic"]=[[jiaobu]]},["fb27_49"]={["down"]=[[fb27_54]],["dsc"]=[[这是一条非常崎岖难行的山路，一路蜿蜒盘山而上，沿途均是葱郁的古柏山林，蔚然森秀。在此处可眺望终南山的景色，只见山险岭峻，山川毓秀。]],["fightBackground"]=[[山外]],["id"]=[[fb27_49]],["name"]=[[山路]],["permission"]=1,["role1"]=[[fb27r49_100]],["role2"]=[[fb27r49_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_45]]},["fb27_50"]={["dsc"]=[[从武功西门出来，路势变急了，这是一条用石块铺成的山路。路两旁光秃秃的，没有什么树木，全是一块块的大石头。这条路好像通往前面的终南山上。北面有一个小村庄，村中正升起冉冉的炊烟。]],["fightBackground"]=[[山外]],["id"]=[[fb27_50]],["name"]=[[武功镇山路]],["permission"]=2,["right"]=[[fb27_51]],["stepMusic"]=[[jiaobu]]},["fb27_51"]={["dsc"]=[[一条山路弯弯曲曲地通向山上。北面的山上好像有一片柏树林，树林中隐隐露出亭子的一角，南面就是上山的路。]],["fightBackground"]=[[山外]],["id"]=[[fb27_51]],["item1"]=[[qdpd3]],["left"]=[[fb27_50]],["name"]=[[山路]],["permission"]=2,["rightDown"]=[[fb27_56]],["rightUp"]=[[fb27_46]],["stepMusic"]=[[jiaobu]]},["fb27_52"]={["dsc"]=[[你到了一条小河边，河水清澈见底，水中还有几条鱼在嬉戏玩耍。]],["id"]=[[fb27_52]],["name"]=[[小河边]],["permission"]=2,["role1"]=[[fb27r52_100]],["role2"]=[[fb27r52_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_47]]},["fb27_53"]={["dsc"]=[[这是一条位於终南山脚，鲜为人知的小径。四周古木叁天，树林苍翠，遍地山花，枝头啼鸟唱和不绝。往东可看到一条道路。往西北可通往山林深处。]],["id"]=[[fb27_53]],["item1"]=[[fb27item4]],["leftUp"]=[[fb27_48]],["name"]=[[山间小径]],["permission"]=2,["right"]=[[fb27_54]],["role1"]=[[fb27r53_1]],["stepMusic"]=[[jiaobu]]},["fb27_54"]={["dsc"]=[[此处位於终南山山脚。巍峨的终南山，自古以来就是历代名人游览的圣地。往东可看见一座寺庙。往西是一条通往密林的幽静小路。往北可上终南山。]],["fightBackground"]=[[山外]],["id"]=[[fb27_54]],["left"]=[[fb27_53]],["leftDown"]=[[fb27_57]],["name"]=[[道路]],["permission"]=1,["right"]=[[fb27_55]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_49]]},["fb27_55"]={["dsc"]=[[这是一个位於终南山下的小寺庙，庙门横额写着“普光寺”三个大字。由於此庙是上终南山的必经之路，大多数的游客都会在此落脚休息，也因此此处香火也颇为鼎盛。]],["id"]=[[fb27_55]],["item1"]=[[lbr55_3]],["left"]=[[fb27_54]],["name"]=[[普光寺门]],["permission"]=2,["right"]=[[fb27_58]],["role1"]=[[fb27r55_1]],["role2"]=[[fb27r55_2]],["role3"]=[[lbr55_1]],["role4"]=[[lbr55_2]],["stepMusic"]=[[jiaobu]]},["fb27_56"]={["dsc"]=[[这里是山路的尽头，再向东走，就是终南山的山脚了。]],["fightBackground"]=[[山外]],["id"]=[[fb27_56]],["item1"]=[[qdpd2]],["leftUp"]=[[fb27_51]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb27_57]],["stepMusic"]=[[jiaobu]]},["fb27_57"]={["dsc"]=[[这里是终南山的山脚，终南山号称西北的第一山，以山势奇峻，环境清幽著称。这里的山势还很平缓，一道石阶蜿蜒通往山上。]],["fightBackground"]=[[山外]],["id"]=[[fb27_57]],["item1"]=[[qdpd]],["left"]=[[fb27_56]],["name"]=[[终南山脚]],["permission"]=2,["rightUp"]=[[fb27_54]],["role1"]=[[fb27r57_1]],["stepMusic"]=[[jiaobu]]},["fb27_58"]={["dsc"]=[[这里是寺庙的前殿大成殿。殿内青砖铺地，两侧分列哼、哈二将，当中供着肥肥胖胖的弥陀佛，对着你笑嘻嘻的。两边各放几个蒲团，以供僧俗叩拜。当中放着一张长桌，上面点着几支红烛，其上没有任何贡品。]],["id"]=[[fb27_58]],["left"]=[[fb27_55]],["name"]=[[前殿]],["permission"]=2,["right"]=[[fb27_59]],["role1"]=[[fb27r58_1]],["role2"]=[[fb27r58_2]],["stepMusic"]=[[jiaobu]]},["fb27_59"]={["dsc"]=[[正殿供奉着我佛如来，大佛两旁有弟子菩萨，力士、天王、罗汉等，个个慈眉善目。]],["id"]=[[fb27_59]],["item1"]=[[fb27r59_5]],["item2"]=[[fb27r59_6]],["item3"]=[[fb27item205]],["left"]=[[fb27_58]],["name"]=[[正殿]],["permission"]=2,["right"]=[[fb27_60]],["role1"]=[[fb27r59_1]],["role2"]=[[fb27r59_2]],["role3"]=[[fb27r59_3]],["role4"]=[[fb27r59_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_62]]},["fb27_60"]={["dsc"]=[[正殿供奉着我佛如来，大佛两旁有弟子菩萨，力士、天王、罗汉等，个个慈眉善目。]],["id"]=[[fb27_60]],["item1"]=[[fb27item206]],["left"]=[[fb27_59]],["name"]=[[正殿]],["permission"]=2,["right"]=[[fb27_61]],["role1"]=[[fb27r60_1]],["role2"]=[[fb27r60_2]],["role3"]=[[fb27r60_3]],["role4"]=[[fb27r60_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb27_63]]},["fb27_61"]={["dsc"]=[[普光寺后院的一条小路，从正殿直通斋房。]],["id"]=[[fb27_61]],["left"]=[[fb27_60]],["name"]=[[小路]],["permission"]=2,["rightDown"]=[[fb27_64]],["stepMusic"]=[[jiaobu]]},["fb27_62"]={["down"]=[[fb27_59]],["dsc"]=[[正殿供奉着我佛如来，大佛两旁有弟子菩萨，力士、天王、罗汉等，个个慈眉善目。]],["id"]=[[fb27_62]],["item1"]=[[fb27item204]],["name"]=[[正殿]],["permission"]=2,["right"]=[[fb27_63]],["role1"]=[[fb27r62_1]],["role2"]=[[fb27r62_2]],["role3"]=[[fb27r62_3]],["role4"]=[[fb27r62_4]],["stepMusic"]=[[jiaobu]]},["fb27_63"]={["down"]=[[fb27_60]],["dsc"]=[[正殿供奉着我佛如来，大佛两旁有弟子菩萨，力士、天王、罗汉等，个个慈眉善目。]],["id"]=[[fb27_63]],["left"]=[[fb27_62]],["name"]=[[正殿]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb27_64"]={["dsc"]=[[这里既是寺僧用斋的地方，也是做饭的地方。]],["id"]=[[fb27_64]],["item1"]=[[fb27item200]],["item2"]=[[fb27item201]],["item3"]=[[fb27item202]],["leftUp"]=[[fb27_61]],["name"]=[[斋房]],["permission"]=2,["role1"]=[[fb27r64_1]],["stepMusic"]=[[jiaobu]]},["fb27_65"]={["dsc"]=[[这里有几具死去的尸体，散发着阵阵恶臭，令人难以忍受。]],["id"]=[[fb27_65]],["item1"]=[[wabaorenwu19]],["item2"]=[[wabaorenwu12]],["item3"]=[[wabaorenwu14]],["name"]=[[无名洞窟]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb27_66"]={["dsc"]=[[这是一条整齐的石板路，依山而建，随着山势的曲折蜿蜒曲折。由于山势陡了，当初修建这条石阶时肯定费了不小的功夫。走到这里，已经可以看见重阳观的檐角了。]],["id"]=[[fb27_66]],["left"]=[[fb27_46]],["name"]=[[石阶]],["permission"]=2,["right"]=[[fb27_67]],["role1"]=[[fb27_19a]],["stepMusic"]=[[jiaobu]]},["fb27_67"]={["dsc"]=[[这是一条整齐的石板路，依山而建，随着山势的曲折蜿蜒曲折。由于山势陡了，当初修建这条石阶时肯定费了不小的功夫。走到这里，已经可以看见重阳观的檐角了。]],["id"]=[[fb27_67]],["item1"]=[[fubentiaozhuan1]],["left"]=[[fb27_66]],["name"]=[[石阶]],["permission"]=2,["stepMusic"]=[[jiaobu]]}}000000000000000